#!/usr/bin/env python3
"""Run C2 Unit01 recalibration with additional target-safe review depth."""
from pathlib import Path

SOURCE = Path(__file__).with_name('recalibrate_final_arabic_c2_unit01.py')
text = SOURCE.read_text(encoding='utf-8')
marker = 'UPDATES={'
assert text.count(marker) == 1

EXTRA = {
    'ar-c2-u01-p01': "وفي مراجعة مستقلة أعطى المدرس التعريفات بلا أسماء لأشخاص لم يحضروا النقاش، وطلب منهم تصنيف عشر حالات جديدة وذكر سبب كل قرار. اتفق المراجعون في معظم الحالات واختلفوا في حالتين حدوديتين. لم يحسم الفريق الخلاف بالتصويت؛ عاد إلى نوع العلاقة المدعاة وسأل أي صياغة تجعل سبب الاختلاف ظاهرًا. اكتشفوا أن أحد التعريفات يستخدم كلمة عامة تخفي حالتين مختلفتين: غياب عنصر لا يمكن الاستغناء عنه، وغياب عنصر يمكن تعويضه بمسار آخر. ففصلوا الحالتين، ثم أعادوا الاختبار على أمثلة لم تستخدم في بناء التعريف. ساعد ذلك على معرفة ما إذا كانت الصياغة تعلمت الحالات الأولى فقط أم التقطت فرقًا يمكن نقله. كما طلب المدرس من كل طالب حذف شرط واحد من تعريفه وشرح ما الخطأ الجديد الذي يسمح به الحذف. إذا لم يستطع ذكر خطأ، كان الشرط مرشحًا لأن يكون زائدًا. بهذه الطريقة أصبح الاختصار نتيجة اختبار لا تفضيلًا أسلوبيًا، وصار كل عنصر في التعريف يحمل وظيفة يمكن للقارئ تتبعها.",
    'ar-c2-u01-p02': "ثم طلبت الباحثة من فريق ثان قراءة النسختين القديمة والمعدلة من دون معرفة أيهما جاءت أولًا. وجد الفريق أن النسخة المعدلة تفسر الحالات الجديدة بصورة أفضل، لكنه أشار إلى أن أحد الشروط صار واسعًا ويمكن أن يشمل أفعالًا لا يرغب أصحاب النظرية في ضمها. عاد النقاش إذن من الدفاع عن التعديل إلى اختباره ضد الإفراط في الشمول. صاغوا حالة تجمع السبب المتبنى مع تلاعب طويل الأمد لا يدركه الفاعل، وسألوا هل ينبغي عد القرار حرًا بالمعنى نفسه. لم يحتاجوا إلى حل المسألة كلها؛ يكفي أن الحالة كشفت موضعًا يحتاج إلى فصل إضافي أو إلى تضييق الادعاء. كما قارنوا قوة النسخة المعدلة بما تتنبأ به خارج الأمثلة التي ولدت منها. فإذا لم ينتج عنها أي توقع جديد، تصبح فائدتها أقل من مجرد وصف الحالات بعد وقوعها. بهذه المراجعة صار التعديل مطالبًا بأن ينجو من اعتراضين متعاكسين: ألا يكون ضيقًا يفشل أمام الحالات العادية، وألا يكون مرنًا يضم كل نتيجة بعد ظهورها.",
    'ar-c2-u01-p03': "وفي مرحلة لاحقة طلبت هناء من الطلاب مقارنة حالات النجاح العرضي بحالات الخطأ المعقول. شخص يعتمد طريقة جيدة قد يصل أحيانًا إلى نتيجة خاطئة بسبب ظرف نادر، بينما شخص يعتمد طريقًا رديئًا قد يصيب مرة واحدة. إذا جعلنا النتيجة الفعلية وحدها معيار التقييم، سنفضل الثاني في اليوم الذي حالفه فيه الحظ. لذلك سجل الطلاب أداء الطريقة عبر مجموعة حالات ممكنة قريبة من الحالة الأصلية، لا عبر واقعة واحدة فقط. سألوا هل تميل الطريقة إلى التغير عندما يتغير الواقع، وهل تكتشف بعض أخطائها، وهل يستطيع صاحبها الاستجابة لتنبيه معقول. كما ناقشوا فرقًا بين الاعتماد على شاهد واحد والاعتماد على عدة مصادر ليست مستقلة حقًا. تكرار القول لا يزيد الثقة كثيرًا إذا كانت جميع النسخ تعود إلى المصدر الأول نفسه. جعل ذلك «عدد الشهادات» أقل أهمية من بنية الاعتماد بينها. وفي نهاية المراجعة كتبوا لكل اعتقاد شجرة قصيرة تبين أصل الدليل والمسارات التي قد تنقل الخطأ، فصار الحظ قابلًا للتتبع داخل السلسلة بدل أن يظهر فقط بوصفه مفاجأة في النتيجة.",
    'ar-c2-u01-p04': "ثم أجرت المجموعة اختبارًا للمقارنة بين الحالات بدل تقييم كل حالة منفردة. غيرت عاملًا واحدًا في كل مرة: شدة الضغط، إمكان الوصول إلى الحقائق، مقدار الوقت للمراجعة، أو سلطة الشخص داخل الجماعة. إذا تغير الحكم كثيرًا عند عامل واحد، طلبوا تفسيرًا يوضح لماذا يحمل هذا العامل وزنًا خاصًا. وإذا لم يتغير رغم اختلاف كبير، سألوا هل كانوا يعتمدون على انطباع ثابت عن الشخص لا على بنية الموقف. كشف التمرين أن بعض الطلاب يعاقبون النتيجة السيئة حتى عندما تكون غير متوقعة، بينما يخففون الحكم إذا انتهى الفعل نفسه بلا ضرر. أعادوا لذلك تقييم الحالات قبل كشف النتائج النهائية ثم قارنوها بأحكامهم بعد الكشف. ظهر أثر واضح للحظ اللاحق في بعض الإجابات. لم يحاولوا إزالة أثر النتائج من كل حكم؛ أحيانًا يؤثر الضرر في واجب الإصلاح حتى إذا لم يغير تقييم قرار البداية. هذا الفصل بين مسؤولية الاختيار ومسؤولية الاستجابة لما حدث جعل الخريطة أدق وأقل اعتمادًا على نهاية القصة.",
    'ar-c2-u01-p05': "وفي مراجعة مستقلة عرضت ريم الحالات على أشخاص يختلفون في خبرتهم بالمجال، ثم قارنت ليس النتيجة فقط بل الأسباب التي يقدمونها. اتفق بعضهم على القرار واختلفوا في الطريق إليه: خبير ركز على الأثر الطويل، وآخر على الواجب السابق، وثالث على إمكانية إصلاح الضرر. جعل ذلك الفريق يسأل هل الحكم الجيد يحتاج إلى سبب واحد حاكم أم يستطيع جمع أسباب متعددة مع أوزان تتغير بحسب الموقف. لم يحولوا الأوزان إلى أرقام نهائية؛ استخدموها للكشف عن السبب الذي لو تغير سيغير القرار. ثم صاغوا حالات تعاكس ترتيب الأهمية: خطر عاجل يجعل التأخير أكثر سوءًا، وحالة أخرى يكون فيها الانتظار القصير هو الطريق الأقل ضررًا. ساعدت المقارنة على فصل القاعدة العامة عن مهارة التعرف إلى ما يميز الحالة الحالية. كما طلبوا من كل مشارك ذكر قرار سابق كان سيغيره بعد ظهور أثر لم يتوقعه، لا لمعاقبة الحكم القديم بمعرفة لاحقة، بل لفحص القدرة على التعلم من النتائج من دون إعادة كتابة ما كان متاحًا وقت الفعل.",
    'ar-c2-u01-p06': "وفي ختام المهمة أضافت هناء اختبارًا آخر: أعطت الطلاب حجتين تصلان إلى النتيجة نفسها لكن إحداهما تستخدم خمسة تمييزات والأخرى تستخدم اثنين فقط. لم تفترض أن الأقصر أفضل. طلبت منهم حذف كل فرق بالتتابع ومراقبة ما الذي يضيع: هل يتغير الاستنتاج، أم يختفي تفسير حالة حدودية، أم لا يحدث شيء؟ اتضح أن أحد الفروق في الحجة الطويلة لا يؤدي أي عمل، بينما فرقًا واحدًا في الحجة القصيرة كان يخفي حالتين تحتاجان إلى معالجة منفصلة. ثم طلبت إعادة صياغة الحجج لقارئ غير متخصص مع الحفاظ على العلاقات نفسها. عندما احتاج الطالب إلى كلمة تقنية، كان عليه أن يشرح ما الذي تختصره وما الاختبار الذي يرتبط بها. إذا لم يستطع، أصبحت الكلمة مرشحة للحذف. وأخيرًا قارنت المجموعة بين خلاف على التصنيف وخلاف على الوقائع وخلاف على القيمة. قد يتفق شخصان على كل الحالات ثم يختلفان فقط في الاسم، أو يتفقان على الاسم ويختلفان في ما حدث، أو يتفقان على الاثنين ويختلفان في ما ينبغي فعله. فصل هذه المستويات منع النقاش من الدوران حول لفظ واحد عندما يكون موضع النزاع الحقيقي في مكان آخر.",
}

extra_code = "EXTRA = " + repr(EXTRA) + "\nfor _pid, _extra in EXTRA.items():\n    ADD[_pid] = ADD[_pid].rstrip() + ' ' + _extra.strip()\n"
patched = text.replace(marker, extra_code + '\n' + marker, 1)
exec(compile(patched, str(SOURCE), 'exec'), {'__name__': '__main__', '__file__': str(SOURCE)})
